package com.alpharip.staffmod.hud;
import com.alpharip.staffmod.modules.AlphaModule;import com.alpharip.staffmod.modules.AlphaModuleRegistry;import net.minecraft.client.Minecraft;import net.minecraft.entity.item.EntityItem;import net.minecraft.util.MovingObjectPosition;import net.minecraftforge.client.event.RenderGameOverlayEvent;import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
/** Inspects a dropped item entity selected by the crosshair. */
public final class StaffItemEntityInspector{
 private boolean enabled(){AlphaModule m=AlphaModuleRegistry.find("staff-item-entity-inspector");return m!=null&&m.isEnabled()&&m.isUnlocked();}
 @SubscribeEvent public void onOverlay(RenderGameOverlayEvent.Text e){if(e.type!=RenderGameOverlayEvent.ElementType.TEXT||!enabled())return;Minecraft mc=Minecraft.getMinecraft();if(mc==null||mc.thePlayer==null||mc.theWorld==null||mc.fontRendererObj==null||mc.gameSettings.showDebugInfo||mc.objectMouseOver==null||mc.objectMouseOver.typeOfHit!=MovingObjectPosition.MovingObjectType.ENTITY||!(mc.objectMouseOver.entityHit instanceof EntityItem))return;EntityItem x=(EntityItem)mc.objectMouseOver.entityHit;String n=x.getEntityItem()==null?"empty":x.getEntityItem().getDisplayName();int c=x.getEntityItem()==null?0:x.getEntityItem().stackSize;mc.fontRendererObj.drawStringWithShadow("Dropped item: "+n,6,6,0xFFFFFFFF);mc.fontRendererObj.drawStringWithShadow("Count: "+c+" | Age: "+x.getAge()+" ticks",6,18,0xFFFFFFFF);mc.fontRendererObj.drawStringWithShadow(String.format("Position %.1f, %.1f, %.1f",x.posX,x.posY,x.posZ),6,30,0xFFFFFFFF);}
}